-- Enforce tenant-consistent foreign-key relationships.
-- NOT VALID preserves existing rows for audit while enforcing new/changed rows.
begin;
create unique index if not exists customers_id_company_uq on public.customers(id, company_id);
create unique index if not exists offers_id_company_uq on public.offers(id, company_id);
create unique index if not exists offers_id_company_customer_uq on public.offers(id, company_id, customer_id);
create unique index if not exists orders_id_company_uq on public.orders(id, company_id);
create unique index if not exists orders_id_company_customer_uq on public.orders(id, company_id, customer_id);
create unique index if not exists contracts_id_company_uq on public.contracts(id, company_id);
create unique index if not exists contracts_id_company_customer_uq on public.contracts(id, company_id, customer_id);
create unique index if not exists shipments_id_company_uq on public.shipments(id, company_id);
create unique index if not exists shipments_id_company_customer_uq on public.shipments(id, company_id, customer_id);
do $$
begin
  if not exists(select 1 from pg_constraint where conname='offers_customer_company_fk' and conrelid='public.offers'::regclass) then alter table public.offers add constraint offers_customer_company_fk foreign key(customer_id,company_id) references public.customers(id,company_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='orders_customer_company_fk' and conrelid='public.orders'::regclass) then alter table public.orders add constraint orders_customer_company_fk foreign key(customer_id,company_id) references public.customers(id,company_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='orders_offer_company_fk' and conrelid='public.orders'::regclass) then alter table public.orders add constraint orders_offer_company_fk foreign key(offer_id,company_id) references public.offers(id,company_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='orders_offer_customer_fk' and conrelid='public.orders'::regclass) then alter table public.orders add constraint orders_offer_customer_fk foreign key(offer_id,company_id,customer_id) references public.offers(id,company_id,customer_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='contracts_customer_company_fk' and conrelid='public.contracts'::regclass) then alter table public.contracts add constraint contracts_customer_company_fk foreign key(customer_id,company_id) references public.customers(id,company_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='contracts_order_customer_fk' and conrelid='public.contracts'::regclass) then alter table public.contracts add constraint contracts_order_customer_fk foreign key(order_id,company_id,customer_id) references public.orders(id,company_id,customer_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='shipments_customer_company_fk' and conrelid='public.shipments'::regclass) then alter table public.shipments add constraint shipments_customer_company_fk foreign key(customer_id,company_id) references public.customers(id,company_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='shipments_order_customer_fk' and conrelid='public.shipments'::regclass) then alter table public.shipments add constraint shipments_order_customer_fk foreign key(order_id,company_id,customer_id) references public.orders(id,company_id,customer_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='shipments_contract_customer_fk' and conrelid='public.shipments'::regclass) then alter table public.shipments add constraint shipments_contract_customer_fk foreign key(contract_id,company_id,customer_id) references public.contracts(id,company_id,customer_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='payments_customer_company_fk' and conrelid='public.payments'::regclass) then alter table public.payments add constraint payments_customer_company_fk foreign key(customer_id,company_id) references public.customers(id,company_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='payments_order_customer_fk' and conrelid='public.payments'::regclass) then alter table public.payments add constraint payments_order_customer_fk foreign key(order_id,company_id,customer_id) references public.orders(id,company_id,customer_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='documents_customer_company_fk' and conrelid='public.documents'::regclass) then alter table public.documents add constraint documents_customer_company_fk foreign key(customer_id,company_id) references public.customers(id,company_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='documents_offer_company_fk' and conrelid='public.documents'::regclass) then alter table public.documents add constraint documents_offer_company_fk foreign key(offer_id,company_id) references public.offers(id,company_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='documents_offer_customer_fk' and conrelid='public.documents'::regclass) then alter table public.documents add constraint documents_offer_customer_fk foreign key(offer_id,company_id,customer_id) references public.offers(id,company_id,customer_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='documents_order_company_fk' and conrelid='public.documents'::regclass) then alter table public.documents add constraint documents_order_company_fk foreign key(order_id,company_id) references public.orders(id,company_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='documents_order_customer_fk' and conrelid='public.documents'::regclass) then alter table public.documents add constraint documents_order_customer_fk foreign key(order_id,company_id,customer_id) references public.orders(id,company_id,customer_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='documents_contract_company_fk' and conrelid='public.documents'::regclass) then alter table public.documents add constraint documents_contract_company_fk foreign key(contract_id,company_id) references public.contracts(id,company_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='documents_contract_customer_fk' and conrelid='public.documents'::regclass) then alter table public.documents add constraint documents_contract_customer_fk foreign key(contract_id,company_id,customer_id) references public.contracts(id,company_id,customer_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='documents_shipment_company_fk' and conrelid='public.documents'::regclass) then alter table public.documents add constraint documents_shipment_company_fk foreign key(shipment_id,company_id) references public.shipments(id,company_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='documents_shipment_customer_fk' and conrelid='public.documents'::regclass) then alter table public.documents add constraint documents_shipment_customer_fk foreign key(shipment_id,company_id,customer_id) references public.shipments(id,company_id,customer_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='offer_items_offer_company_fk' and conrelid='public.offer_items'::regclass) then alter table public.offer_items add constraint offer_items_offer_company_fk foreign key(offer_id,company_id) references public.offers(id,company_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='order_items_order_company_fk' and conrelid='public.order_items'::regclass) then alter table public.order_items add constraint order_items_order_company_fk foreign key(order_id,company_id) references public.orders(id,company_id) not valid; end if;
  if not exists(select 1 from pg_constraint where conname='contract_files_contract_company_fk' and conrelid='public.contract_files'::regclass) then alter table public.contract_files add constraint contract_files_contract_company_fk foreign key(contract_id,company_id) references public.contracts(id,company_id) not valid; end if;
end $$;
commit;
